1	<?php
2	
3	namespace App\Http\Controllers\Api\Internal;
4	
5	use App\Http\Controllers\Api\ApiController;
6	use App\Models\Core\Professional\BrandPartnerLink;
7	use App\Models\Core\Professional\Professional;
8	use App\Models\Core\Professional\ProfessionalIntegration;
9	use App\Models\Core\Professional\Service;
10	use App\Models\Core\Site\Block;
11	use App\Models\Core\Site\Site;
12	use App\Models\Core\Site\SiteMedia;
13	use Illuminate\Http\JsonResponse;
14	use Illuminate\Http\Request;
15	use Illuminate\Support\Facades\Validator;
16	use Illuminate\Validation\ValidationException;
17	
18	// V2: Internal endpoint for Hydrogen loaders. Validates an affiliate slug belongs to
19	// a brand and returns the affiliate's full sitepage payload: gallery, content images,
20	// every link category (social + content + education + events + custom + synthesized
21	// booking), bio + about, document, newsletter, services, and booking.
22	//
23	// Every section that has a Draft/Live toggle in the dashboard is returned as an
24	// envelope `{state: "draft"|"live", data: <payload>|null}`. Hydrogen reads `state`
25	// to decide whether to mount the section; `data` is always null when draft so draft
26	// content never leaks publicly even if Hydrogen has a bug. Per-row Draft/Live (links)
27	// is handled server-side: is_active=false rows are simply filtered out.
28	class HydrogenAffiliateController extends ApiController
29	{
30	    public function show(Request $request): JsonResponse
31	    {
32	        $validator = Validator::make($request->query(), [
33	            'shop_domain' => ['required', 'string', 'max:255'],
34	            'slug' => ['required', 'string', 'max:255'],
35	        ]);
36	
37	        if ($validator->fails()) {
38	            throw new ValidationException($validator);
39	        }
40	
41	        $validated = $validator->validated();
42	        $shopDomain = strtolower(trim($validated['shop_domain']));
43	        $slug = strtolower(trim($validated['slug']));
44	
45	        $integration = ProfessionalIntegration::query()
46	            ->where('shopify_shop_domain', $shopDomain)
47	            ->where('provider', ProfessionalIntegration::PROVIDER_SHOPIFY)
48	            ->first();
49	
50	        if (! $integration) {
51	            return $this->error('Brand not found.', 404);
52	        }
53	
54	        $affiliate = Professional::query()
55	            ->where('handle_lc', $slug)
56	            ->whereNull('deleted_at')
57	            ->first();
58	
59	        if (! $affiliate || $affiliate->status !== 'active') {
60	            return $this->error('Affiliate not found.', 404);
61	        }
62	
63	        $linked = BrandPartnerLink::query()
64	            ->where('brand_professional_id', $integration->professional_id)
65	            ->where('affiliate_professional_id', $affiliate->id)
66	            ->exists();
67	
68	        if (! $linked) {
69	            return $this->error('Affiliate not found.', 404);
70	        }
71	
72	        $site = Site::where('professional_id', $affiliate->id)->first();
73	
74	        // Preload the site's section blocks once — every envelope helper reads
75	        // `is_active` off this collection instead of issuing one exists query
76	        // per section. Keyed by block_type for O(1) lookups.
77	        $sections = $site
78	            ? $site->sectionBlocks()->whereNull('deleted_at')->get()->keyBy('block_type')
79	            : collect();
80	
81	        // Booking data is needed both as its own section and for synthesizing
82	        // a link into the links list, so compute it once and pass the result
83	        // into getAffiliateLinks().
84	        $booking = $this->getAffiliateBooking($site, $sections);
85	
86	        // no-store: payload shape has evolved (e.g. links.id added in b9de807).
87	        // Prevent Oxygen/CDN from caching a stale shape across deploys.
88	        return $this->success([
89	            'affiliate_id' => (string) $affiliate->id,
90	            'name' => $affiliate->display_name,
91	            'slug' => $affiliate->handle,
92	            'gallery' => $this->getAffiliateGallery($site, $sections),
93	            // Content pool — no section-level gate in the dashboard, so no
94	            // envelope. Hydrogen merges these over brand defaults.
95	            'content_images' => $this->getAffiliateContent($site),
96	            'links' => $this->getAffiliateLinks($site, $booking),
97	            'bio' => $this->getAffiliateBio($affiliate, $sections),
98	            'document' => $this->getAffiliateDocument($site),
99	            'newsletter' => $this->getAffiliateNewsletter($sections),
100	            'services' => $this->getAffiliateServices($site, $affiliate->id, $sections),
101	            'booking' => $booking,
102	            // Shop has no content envelope (products come from Shopify), but
103	            // the block_id is needed so Hydrogen can fire click tracking when
104	            // the visitor opens the shop card.
105	            'shop' => $this->sectionEnvelope($sections, 'shop', fn () => null),
106	        ])->header('Cache-Control', 'no-store');
107	    }
108	
109	    /**
110	     * Returns affiliate services for the Hydrogen "Services & Pricing" section.
111	     * Standalone endpoint kept for back-compat / lazy fetches; the same shape
112	     * also appears inside show() under the `services` envelope's `data`.
113	     */
114	    public function services(Request $request): JsonResponse
115	    {
116	        $validator = Validator::make($request->query(), [
117	            'shop_domain' => ['required', 'string', 'max:255'],
118	            'slug' => ['required', 'string', 'max:255'],
119	        ]);
120	
121	        if ($validator->fails()) {
122	            throw new ValidationException($validator);
123	        }
124	
125	        $validated = $validator->validated();
126	        $shopDomain = strtolower(trim($validated['shop_domain']));
127	        $slug = strtolower(trim($validated['slug']));
128	
129	        $integration = ProfessionalIntegration::query()
130	            ->where('shopify_shop_domain', $shopDomain)
131	            ->where('provider', ProfessionalIntegration::PROVIDER_SHOPIFY)
132	            ->first();
133	
134	        if (! $integration) {
135	            return $this->error('Brand not found.', 404);
136	        }
137	
138	        $affiliate = Professional::query()
139	            ->where('handle_lc', $slug)
140	            ->whereNull('deleted_at')
141	            ->first();
142	
143	        if (! $affiliate || $affiliate->status !== 'active') {
144	            return $this->error('Affiliate not found.', 404);
145	        }
146	
147	        $linked = BrandPartnerLink::query()
148	            ->where('brand_professional_id', $integration->professional_id)
149	            ->where('affiliate_professional_id', $affiliate->id)
150	            ->exists();
151	
152	        if (! $linked) {
153	            return $this->error('Affiliate not found.', 404);
154	        }
155	
156	        $site = Site::where('professional_id', $affiliate->id)->first();
157	
158	        return $this->success($this->buildServicesData($site, $affiliate->id));
159	    }
160	
161	    // ── Section envelope helper ──────────────────────────────────────────────
162	    //
163	    // Shape: ['state' => 'draft'|'live', 'data' => mixed|null].
164	    // Pass the pre-loaded sections collection so we don't re-query per call.
165	    // If the section row doesn't exist (edge case during rollout) we treat it
166	    // as draft, matching the dashboard's "missing = not yet published" rule.
167	
168	    /**
169	     * @param  \Illuminate\Support\Collection<string, Block>  $sections
170	     * @return array{state: string, data: mixed}
171	     */
172	    private function sectionEnvelope($sections, string $blockType, callable $buildData): array
173	    {
174	        $section = $sections->get($blockType);
175	        $isLive = $section !== null && (bool) $section->is_active;
176	
177	        return [
178	            'state' => $isLive ? 'live' : 'draft',
179	            'block_id' => $section?->id,
180	            'data' => $isLive ? $buildData($section) : null,
181	        ];
182	    }
183	
184	    // ── Gallery ──────────────────────────────────────────────────────────────
185	
186	    /**
187	     * Returns the gallery envelope. When live, `data` is an ordered array of
188	     * `{url, alt_text, caption, kind, poster, duration_ms}` rows covering both
189	     * images and videos (the dashboard unifies them in one grid). Per-row filter
190	     * keeps only ready rows so Hydrogen never sees processing placeholders.
191	     *
192	     * @param  \Illuminate\Support\Collection<string, Block>  $sections
193	     * @return array{state: string, data: array|null}
194	     */
195	    private function getAffiliateGallery(?Site $site, $sections): array
196	    {
197	        return $this->sectionEnvelope($sections, 'gallery', function () use ($site): array {
198	            if (! $site) {
199	                return [];
200	            }
201	
202	            return SiteMedia::query()
203	                ->where('site_id', $site->id)
204	                ->where('pool', SiteMedia::POOL_GALLERY)
205	                ->where('is_active', true)
206	                ->where('processing_state', SiteMedia::PROCESSING_STATE_READY)
207	                ->with('mediaVariants')
208	                ->orderBy('sort_order')
209	                ->get()
210	                ->map(fn (SiteMedia $media) => $this->buildGalleryItem($media))
211	                ->filter(fn (?array $item) => $item !== null && $item['url'] !== '')
212	                ->values()
213	                ->all();
214	        });
215	    }
216	
217	    /**
218	     * Project a SiteMedia row to the Hydrogen gallery shape. Videos prefer the
219	     * HLS stream URL (plays natively in Safari + hls.js elsewhere) and fall
220	     * back to progressive MP4 variants; images use the optimised WebP.
221	     *
222	     * @return array{url: string, alt_text: string|null, caption: string|null, kind: string, poster: string|null, duration_ms: int|null}|null
223	     */
224	    private function buildGalleryItem(SiteMedia $media): ?array
225	    {
226	        $isVideo = $media->media_type === SiteMedia::MEDIA_TYPE_VIDEO;
227	
228	        if ($isVideo) {
229	            $streams = [];
230	            $variants = [];
231	            $poster = null;
232	            foreach ($media->mediaVariants as $mv) {
233	                if ($mv->artifact_type === 'hls_playlist') {
234	                    $streams[$mv->variant_key] = $mv->url;
235	                } elseif ($mv->artifact_type === 'mp4') {
236	                    $variants[$mv->variant_key] = $mv->url;
237	                } elseif ($mv->artifact_type === 'poster') {
238	                    $poster = $mv->url;
239	                }
240	            }
241	            // Prefer HLS; fall back through progressive MP4 variants to any
242	            // remaining URL. Mirrors Sidest-Hydrogen's pickVideoSrc() order.
243	            $url = $streams['optimized']
244	                ?? $streams['maximized']
245	                ?? $variants['optimized']
246	                ?? $variants['maximized']
247	                ?? $variants['original']
248	                ?? '';
249	
250	            return [
251	                'url' => $url,
252	                'alt_text' => $media->alt_text,
253	                'caption' => $media->caption,
254	                'kind' => 'video',
255	                'poster' => $poster,
256	                'duration_ms' => $media->duration_ms,
257	            ];
258	        }
259	
260	        $variantUrls = $media->variantUrls();
261	        $url = $variantUrls['optimized'] ?? $variantUrls['original'] ?? '';
262	
263	        return [
264	            'url' => $url,
265	            'alt_text' => $media->alt_text,
266	            'caption' => $media->caption,
267	            'kind' => 'image',
268	            'poster' => null,
269	            'duration_ms' => null,
270	        ];
271	    }
272	
273	    // ── Content images ───────────────────────────────────────────────────────
274	
275	    private function getAffiliateContent(?Site $site): array
276	    {
277	        if (! $site) {
278	            return [];
279	        }
280	
281	        return SiteMedia::query()
282	            ->where('site_id', $site->id)
283	            ->where('pool', SiteMedia::POOL_CONTENT)
284	            ->where('is_active', true)
285	            ->where('processing_state', SiteMedia::PROCESSING_STATE_READY)
286	            ->with('mediaVariants')
287	            ->orderBy('sort_order')
288	            ->get()
289	            ->map(fn (SiteMedia $media) => [
290	                'url' => $media->variantUrls()['optimized'] ?? null,
291	                'alt_text' => $media->alt_text,
292	            ])
293	            ->filter(fn (array $item) => $item['url'] !== null)
294	            ->values()
295	            ->all();
296	    }
297	
298	    // ── Links (all categories + synthesized booking) ─────────────────────────
299	
300	    /**
301	     * Returns every live link block the affiliate has, across every category
302	     * (social, content, education, events, custom). Each link is tagged with
303	     * `category` and, for platform-tagged rows, `platform`. Booking is not a
304	     * link block on the dashboard side, but Hydrogen wants to render it
305	     * alongside the other links — when the booking section is live, we
306	     * synthesize a `{category: 'booking'}` row at the end of the list.
307	     *
308	     * @param  array{state: string, data: array|null}  $bookingEnvelope
309	     */
