622	            $settings = is_array($section->settings) ? $section->settings : [];
623	            $bookingUrl = trim((string) ($settings['booking_url'] ?? ''));
624	
625	            // Platform is stored next to booking_url when known (calendly, acuity,
626	            // etc.) so themes can pick a wordmark; missing platform = generic "book now" CTA.
627	            $platform = is_string($settings['platform'] ?? null)
628	                ? strtolower(trim((string) $settings['platform']))
629	                : null;
630	
