225	    {
226	        $isVideo = $media->media_type === SiteMedia::MEDIA_TYPE_VIDEO;
227	
228	        if ($isVideo) {
229	            $streams = [];
230	            $variants = [];
231	            $poster = null;
232	            foreach ($media->mediaVariants as $mv) {
233	                if ($mv->artifact_type === 'hls_playlist') {
234	                    $streams[$mv->variant_key] = $mv->url;
235	                } elseif ($mv->artifact_type === 'mp4') {
236	                    $variants[$mv->variant_key] = $mv->url;
237	                } elseif ($mv->artifact_type === 'poster') {
238	                    $poster = $mv->url;
239	                }
240	            }
241	            // Prefer HLS; fall back through progressive MP4 variants to any
242	            // remaining URL. Mirrors Sidest-Hydrogen's pickVideoSrc() order.
243	            $url = $streams['optimized']
244	                ?? $streams['maximized']
245	                ?? $variants['optimized']
246	                ?? $variants['maximized']
247	                ?? $variants['original']
248	                ?? '';
249	
250	            return [
251	                'url' => $url,
252	                'alt_text' => $media->alt_text,
253	                'caption' => $media->caption,
254	                'kind' => 'video',
255	                'poster' => $poster,
256	                'duration_ms' => $media->duration_ms,
257	            ];
258	        }
259	
260	        $variantUrls = $media->variantUrls();
261	        $url = $variantUrls['optimized'] ?? $variantUrls['original'] ?? '';
262	
263	        return [
264	            'url' => $url,
265	            'alt_text' => $media->alt_text,
266	            'caption' => $media->caption,
267	            'kind' => 'image',
268	            'poster' => null,
269	            'duration_ms' => null,
270	        ];
271	    }
272	
273	    // ── Content images ───────────────────────────────────────────────────────
274	
275	    private function getAffiliateContent(?Site $site): array
276	    {
277	        if (! $site) {
278	            return [];
279	        }
280	
281	        return SiteMedia::query()
282	            ->where('site_id', $site->id)
283	            ->where('pool', SiteMedia::POOL_CONTENT)
284	            ->where('is_active', true)
285	            ->where('processing_state', SiteMedia::PROCESSING_STATE_READY)
286	            ->with('mediaVariants')
287	            ->orderBy('sort_order')
288	            ->get()
289	            ->map(fn (SiteMedia $media) => [
290	                'url' => $media->variantUrls()['optimized'] ?? null,
291	                'alt_text' => $media->alt_text,
292	            ])
293	            ->filter(fn (array $item) => $item['url'] !== null)
294	            ->values()
295	            ->all();
296	    }
297	
298	    // ── Links (all categories + synthesized booking) ─────────────────────────
299	
300	    /**
301	     * Returns every live link block the affiliate has, across every category
302	     * (social, content, education, events, custom). Each link is tagged with
303	     * `category` and, for platform-tagged rows, `platform`. Booking is not a
304	     * link block on the dashboard side, but Hydrogen wants to render it
305	     * alongside the other links — when the booking section is live, we
306	     * synthesize a `{category: 'booking'}` row at the end of the list.
307	     *
308	     * @param  array{state: string, data: array|null}  $bookingEnvelope
309	     */
310	    private function getAffiliateLinks(?Site $site, array $bookingEnvelope): array
311	    {
312	        if (! $site) {
313	            return [];
314	        }
315	
316	        $rows = Block::query()
317	            ->where('site_id', $site->id)
318	            ->where('block_group', 'links')
319	            ->where('is_active', true)
320	            ->whereNull('deleted_at')
321	            ->orderBy('sort_order')
322	            ->get()
323	            ->map(function (Block $block): array {
324	                $settings = is_array($block->settings) ? $block->settings : [];
325	                $platform = is_string($settings['platform'] ?? null)
326	                    ? strtolower(trim((string) $settings['platform']))
327	                    : null;
328	                $platform = $platform !== '' ? $platform : null;
329	                // Category lives in settings to avoid a schema change for
330	                // what is effectively a free-form tag. Default to 'custom'
331	                // for older rows that pre-date the category field.
332	                $category = is_string($settings['category'] ?? null)
333	                    ? strtolower(trim((string) $settings['category']))
334	                    : 'custom';
335	
336	                $title = is_string($block->title) ? trim($block->title) : '';
337	                $url = is_string($block->url) ? trim($block->url) : '';
338	
339	                // Resilience: older link rows can have empty title/url at rest
340	                // — settings.platform + settings.handle are the source of truth
341	                // there. Rebuild both from the platform config so the row still
342	                // renders on Hydrogen without requiring a backfill migration.
343	                if (($title === '' || $url === '') && $platform !== null) {
344	                    $config = config("sidest.social_platforms.{$platform}");
345	                    $handle = is_string($settings['handle'] ?? null)
346	                        ? trim((string) $settings['handle'])
347	                        : '';
348	                    if (is_array($config)) {
349	                        if ($title === '' && is_string($config['display_name'] ?? null)) {
350	                            $title = (string) $config['display_name'];
351	                        }
352	                        if ($url === '' && $handle !== '' && is_string($config['url_template'] ?? null)) {
353	                            $url = str_replace('{handle}', $handle, (string) $config['url_template']);
354	                        }
355	                    }
356	                }
357	
358	                return [
359	                    'id' => (string) $block->id,
360	                    'title' => $title,
361	                    'url' => $url,
362	                    'category' => $category !== '' ? $category : 'custom',
363	                    'platform' => $platform,
364	                ];
365	            })
366	            ->filter(fn (array $item) => $item['title'] !== '' && $item['url'] !== '')
367	            ->values()
368	            ->all();
369	
370	        // Append the synthesized booking link when booking is live + resolved.
371	        // Keeping this controller-side means themes have a single list to
372	        // render rather than special-casing booking everywhere.
373	        if ($bookingEnvelope['state'] === 'live' && is_array($bookingEnvelope['data'])) {
374	            $rows[] = [
375	                'title' => (string) ($bookingEnvelope['data']['title'] ?? 'Book now'),
376	                'url' => (string) ($bookingEnvelope['data']['resolved_url'] ?? ''),
377	                'category' => 'booking',
378	                'platform' => is_string($bookingEnvelope['data']['platform'] ?? null)
379	                    ? $bookingEnvelope['data']['platform']
380	                    : null,
381	            ];
382	            // Filter out the booking link if its url ended up empty.
383	            $rows = array_values(array_filter(
384	                $rows,
385	                fn (array $item) => $item['url'] !== '',
386	            ));
387	        }
388	
389	        return $rows;
390	    }
391	
392	    // ── Bio + credentials + experience ───────────────────────────────────────
393	
394	    /**
395	     * @param  \Illuminate\Support\Collection<string, Block>  $sections
396	     * @return array{state: string, data: array|null}
397	     */
398	    private function getAffiliateBio(Professional $affiliate, $sections): array
399	    {
400	        return $this->sectionEnvelope($sections, 'bio', function () use ($affiliate): array {
401	            $about = is_array($affiliate->about) ? $affiliate->about : [];
402	            $credentials = is_array($about['credentials'] ?? null) ? $about['credentials'] : [];
403	            $experience = is_array($about['experience'] ?? null) ? $about['experience'] : [];
404	
405	            return [
406	                'text' => (string) ($affiliate->bio ?? ''),
407	                'credentials' => array_values(array_filter(array_map(
408	                    fn ($row) => $this->normaliseCredential($row),
409	                    $credentials,
410	                ))),
411	                'experience' => array_values(array_filter(array_map(
412	                    fn ($row) => $this->normaliseExperience($row),
413	                    $experience,
414	                ))),
415	            ];
416	        });
417	    }
418	
419	    /**
420	     * Normalise a credential row from the about JSONB column. The dashboard
421	     * sometimes stamps client-side UUIDs; we strip them so the wire shape is
422	     * stable for Hydrogen.
423	     */
424	    private function normaliseCredential($row): ?array
425	    {
426	        if (! is_array($row)) {
427	            return null;
428	        }
429	        $title = trim((string) ($row['title'] ?? ''));
430	        if ($title === '') {
431	            return null;
432	        }
433	
434	        return [
435	            'title' => $title,
436	            'issuer' => trim((string) ($row['issuer'] ?? '')),
437	            'year' => isset($row['year']) && $row['year'] !== '' ? (string) $row['year'] : null,
438	        ];
439	    }
440	
441	    /**
442	     * Dashboard writes experience as {role, place, start, end, description}.
443	     * Project to the Hydrogen contract {title, organisation, period} so the
444	     * wire shape mirrors credentials and the theme layer doesn't have to know
445	     * about the source schema differences.
446	     */
447	    private function normaliseExperience($row): ?array
448	    {
449	        if (! is_array($row)) {
450	            return null;
451	        }
452	
453	        // Accept both the current dashboard schema (role/place) and the older
454	        // Hydrogen contract names (title/organisation) so pre-migration rows
455	        // don't silently drop.
456	        $title = trim((string) ($row['role'] ?? $row['title'] ?? ''));
457	        if ($title === '') {
458	            return null;
459	        }
460	
461	        $organisation = trim((string) (
462	            $row['place']
463	            ?? $row['organisation']
464	            ?? $row['organization']
465	            ?? ''
466	        ));
467	
468	        $start = isset($row['start']) && $row['start'] !== '' ? (string) $row['start'] : null;
469	        // A null `end` means "currently active" per the dashboard's
470	        // ExperienceEditorModal contract — render as "Current" so the public
471	        // site reads like a CV, not a blank field.
472	        $rawEnd = $row['end'] ?? null;
473	        $end = is_string($rawEnd) && $rawEnd !== '' ? $rawEnd : null;
474	
475	        if ($start !== null) {
476	            $period = $start.' – '.($end ?? 'Current');
477	        } elseif (isset($row['period']) && $row['period'] !== '') {
478	            $period = (string) $row['period'];
479	        } else {
480	            $period = null;
481	        }
482	
483	        return [
484	            'title' => $title,
485	            'organisation' => $organisation,
486	            'period' => $period,
487	        ];
488	    }
489	
490	    // ── Document ─────────────────────────────────────────────────────────────
491	
492	    /**
493	     * Document is gated per-row (SiteMedia.is_active), not at the section
494	     * level — the dashboard's Draft/Live toggle writes is_enabled which maps
495	     * directly to SiteMedia.is_active, and there is no separate "documents"
496	     * section block that also needs flipping. If a ready + active row exists
497	     * the envelope is 'live', otherwise 'draft'.
498	     *
499	     * @return array{state: string, data: array|null}
500	     */
501	    private function getAffiliateDocument(?Site $site): array
502	    {
503	        $media = $site
504	            ? SiteMedia::query()
505	                ->where('site_id', $site->id)
506	                ->where('pool', SiteMedia::POOL_DOCUMENTS)
507	                ->where('is_active', true)
508	                ->where('processing_state', SiteMedia::PROCESSING_STATE_READY)
509	                ->orderByDesc('created_at')
510	                ->first()
511	            : null;
512	
513	        if (! $media) {
514	            return ['state' => 'draft', 'data' => null];
515	        }
516	
517	        return [
518	            'state' => 'live',
519	            'data' => [
520	                // Raw id — Hydrogen uses it to build a same-origin proxy URL
521	                // (e.g. /api/document/{id}) so react-pdf can fetch bytes
522	                // without tripping CORS. The absolute download_url below is
523	                // still used by the Download button, which triggers a
524	                // browser navigation and is not subject to CORS.
525	                'id' => (string) $media->id,
526	                'title' => $media->alt_text,
527	                'caption' => $media->caption,
528	                // Absolute URL to the backend download redirect (signed R2
529	                // URL issued server-side) so the Hydrogen payload never
530	                // carries R2 credentials.
531	                'download_url' => url('/api/public/documents/'.$media->id.'/download'),
532	                'mime' => $media->original_mime,
533	                'size_bytes' => $media->original_size_bytes,
534	            ],
535	        ];
536	    }
537	
538	    // ── Newsletter ───────────────────────────────────────────────────────────
539	
540	    /**
541	     * @param  \Illuminate\Support\Collection<string, Block>  $sections
542	     * @return array{state: string, data: array|null}
543	     */
544	    private function getAffiliateNewsletter($sections): array
545	    {
546	        return $this->sectionEnvelope($sections, 'newsletter', function (Block $section): array {
547	            $settings = is_array($section->settings) ? $section->settings : [];
548	
549	            return [
550	                'headline' => (string) ($settings['headline'] ?? ''),
551	                'description' => (string) ($settings['description'] ?? ''),
552	                'cta_label' => (string) ($settings['cta_label'] ?? ''),
553	            ];
554	        });
555	    }
556	
557	    // ── Services ─────────────────────────────────────────────────────────────
558	
559	    /**
560	     * @param  \Illuminate\Support\Collection<string, Block>  $sections
561	     * @return array{state: string, data: array|null}
562	     */
563	    private function getAffiliateServices(?Site $site, string $affiliateId, $sections): array
564	    {
565	        return $this->sectionEnvelope($sections, 'services', function () use ($site, $affiliateId) {
566	            return $this->buildServicesData($site, $affiliateId);
567	        });
568	    }
569	
570	    /**
571	     * Builds the services payload shared by the envelope and the standalone
572	     * /affiliate-services endpoint. Keeping them in one place means the two
573	     * consumers can never drift.
574	     */
575	    private function buildServicesData(?Site $site, string $affiliateId): array
576	    {
577	        $settings = is_array($site?->settings) ? $site->settings : [];
578	        $bookingMode = strtolower((string) ($settings['booking_mode'] ?? 'manual'));
579	        $manualBookingUrl = trim((string) ($settings['manual_booking_url'] ?? ''));
580	
581	        $services = Service::query()
582	            ->with('category:id,title')
583	            ->where('professional_id', $affiliateId)
584	            ->where('is_active', true)
585	            ->whereNull('deleted_at')
586	            ->orderBy('sort_order')
587	            ->orderBy('created_at')
588	            ->get()
589	            ->map(fn (Service $service): array => [
590	                'id' => $service->id,
591	                'title' => $service->title,
592	                'description' => $service->description,
593	                'price_cents' => $service->price_cents,
594	                'currency_code' => $service->currency_code,
595	                'duration_minutes' => $service->duration_minutes,
596	                'category' => $service->category?->title ?? 'Services',
597	            ])
598	            ->values()
599	            ->all();
600	
601	        return [
602	            'booking_mode' => $bookingMode,
603	            'manual_booking_url' => $manualBookingUrl !== '' ? $manualBookingUrl : null,
604	            'services' => $services,
605	        ];
606	    }
607	
608	    // ── Booking ──────────────────────────────────────────────────────────────
609	
610	    /**
611	     * Booking data lives on the `booking` section block's settings — the
612	     * section-level toggle is the single gate (no separate booking section
613	     * visibility state to reconcile). When live + a booking URL is set,
614	     * returns the resolved URL; otherwise data is null.
615	     *
616	     * @param  \Illuminate\Support\Collection<string, Block>  $sections
617	     * @return array{state: string, data: array|null}
618	     */
619	    private function getAffiliateBooking(?Site $site, $sections): array
620	    {
621	        return $this->sectionEnvelope($sections, 'booking', function (Block $section): ?array {
622	            $settings = is_array($section->settings) ? $section->settings : [];
623	            $bookingUrl = trim((string) ($settings['booking_url'] ?? ''));
624	
625	            // Platform is stored next to booking_url when known (calendly, acuity,
626	            // etc.) so themes can pick a wordmark; missing platform = generic "book now" CTA.
627	            $platform = is_string($settings['platform'] ?? null)
628	                ? strtolower(trim((string) $settings['platform']))
629	                : null;
630	
631	            // Title override — affiliate may want "Book a consult" instead of "Book now".
632	            $title = is_string($settings['title'] ?? null)
633	                ? trim((string) $settings['title'])
634	                : '';
635	
636	            if ($bookingUrl === '') {
637	                return null;
638	            }
639	
640	            return [
641	                'platform' => $platform !== '' ? $platform : null,
642	                'path' => $bookingUrl,
643	                // Backend currently stores the fully-resolved URL in settings.booking_url
644	                // (the dashboard normalises before save). If/when we switch to storing
645	                // platform+handle separately, resolve here.
646	                'resolved_url' => $bookingUrl,
647	                'title' => $title !== '' ? $title : 'Book now',
648	            ];
649	        });
650	    }
651	}
