3	use Illuminate\Support\Facades\Route;
4	
5	use function Pest\Laravel\getJson;
6	
7	// #PR-001: VerifyHydrogenApiKey must fail closed when no key is configured
8	// outside local/testing. A regression here re-opens every /internal/hydrogen/*
9	// route — including the deployment-token endpoint that can rewrite a brand's
10	// storefront — to anonymous traffic the moment HYDROGEN_API_KEY goes missing
11	// on a production deploy.
12	
13	beforeEach(function () {
14	    Route::middleware('hydrogen.key')
15	        ->get('/__test/hydrogen-guard', fn () => response()->json(['ok' => true]));
16	});
17	
18	it('allows the dev bypass through when env is testing and no key is configured', function () {
19	    config()->set('services.hydrogen.api_key', '');
20	
21	    getJson('/__test/hydrogen-guard')
22	        ->assertOk()
23	        ->assertJson(['ok' => true]);
24	});
25	
26	it('returns 500 (fails closed) when env is production and no key is configured', function () {
27	    config()->set('services.hydrogen.api_key', '');
28	    app()['env'] = 'production';
29	
30	    getJson('/__test/hydrogen-guard')->assertStatus(500);
31	});
32	
33	it('returns 500 (fails closed) when env is staging and no key is configured', function () {
34	    config()->set('services.hydrogen.api_key', '');
35	    app()['env'] = 'staging';
36	
37	    getJson('/__test/hydrogen-guard')->assertStatus(500);
38	});
39	
40	it('returns 403 when key is configured but the request header is missing', function () {
41	    config()->set('services.hydrogen.api_key', 'secret-key');
42	
43	    getJson('/__test/hydrogen-guard')
44	        ->assertStatus(403)
45	        ->assertJson(['message' => 'Invalid or missing API key.']);
46	});
47	
48	it('returns 403 when key is configured and the request header is wrong', function () {
49	    config()->set('services.hydrogen.api_key', 'secret-key');
50	
51	    getJson('/__test/hydrogen-guard', ['X-Hydrogen-Api-Key' => 'wrong-key'])
52	        ->assertStatus(403);
53	});
54	
55	it('passes through when key is configured and a matching header is provided', function () {
56	    config()->set('services.hydrogen.api_key', 'secret-key');
57	
58	    getJson('/__test/hydrogen-guard', ['X-Hydrogen-Api-Key' => 'secret-key'])
59	        ->assertOk()
60	        ->assertJson(['ok' => true]);
61	});
