217	    /**
218	     * Project a SiteMedia row to the Hydrogen gallery shape. Videos prefer the
219	     * HLS stream URL (plays natively in Safari + hls.js elsewhere) and fall
220	     * back to progressive MP4 variants; images use the optimised WebP.
221	     *
222	     * @return array{url: string, alt_text: string|null, caption: string|null, kind: string, poster: string|null, duration_ms: int|null}|null
223	     */
224	    private function buildGalleryItem(SiteMedia $media): ?array
225	    {
226	        $isVideo = $media->media_type === SiteMedia::MEDIA_TYPE_VIDEO;
227	
228	        if ($isVideo) {
229	            $streams = [];
230	            $variants = [];
231	            $poster = null;
232	            foreach ($media->mediaVariants as $mv) {
233	                if ($mv->artifact_type === 'hls_playlist') {
234	                    $streams[$mv->variant_key] = $mv->url;
235	                } elseif ($mv->artifact_type === 'mp4') {
236	                    $variants[$mv->variant_key] = $mv->url;
237	                } elseif ($mv->artifact_type === 'poster') {
238	                    $poster = $mv->url;
239	                }
240	            }
241	            // Prefer HLS; fall back through progressive MP4 variants to any
242	            // remaining URL. Mirrors Sidest-Hydrogen's pickVideoSrc() order.
243	            $url = $streams['optimized']
244	                ?? $streams['maximized']
245	                ?? $variants['optimized']
246	                ?? $variants['maximized']
247	                ?? $variants['original']
248	                ?? '';
249	
250	            return [
251	                'url' => $url,
252	                'alt_text' => $media->alt_text,
253	                'caption' => $media->caption,
254	                'kind' => 'video',
255	                'poster' => $poster,
256	                'duration_ms' => $media->duration_ms,
257	            ];
258	        }
259	
260	        $variantUrls = $media->variantUrls();
261	        $url = $variantUrls['optimized'] ?? $variantUrls['original'] ?? '';
262	
263	        return [
264	            'url' => $url,
265	            'alt_text' => $media->alt_text,
266	            'caption' => $media->caption,
267	            'kind' => 'image',
268	            'poster' => null,
269	            'duration_ms' => null,
270	        ];
271	    }
