300	    /**
301	     * Returns every live link block the affiliate has, across every category
302	     * (social, content, education, events, custom). Each link is tagged with
303	     * `category` and, for platform-tagged rows, `platform`. Booking is not a
304	     * link block on the dashboard side, but Hydrogen wants to render it
305	     * alongside the other links — when the booking section is live, we
306	     * synthesize a `{category: 'booking'}` row at the end of the list.
307	     *
308	     * @param  array{state: string, data: array|null}  $bookingEnvelope
309	     */
310	    private function getAffiliateLinks(?Site $site, array $bookingEnvelope): array
311	    {
312	        if (! $site) {
313	            return [];
314	        }
315	
316	        $rows = Block::query()
317	            ->where('site_id', $site->id)
318	            ->where('block_group', 'links')
319	            ->where('is_active', true)
320	            ->whereNull('deleted_at')
321	            ->orderBy('sort_order')
322	            ->get()
323	            ->map(function (Block $block): array {
324	                $settings = is_array($block->settings) ? $block->settings : [];
325	                $platform = is_string($settings['platform'] ?? null)
326	                    ? strtolower(trim((string) $settings['platform']))
327	                    : null;
328	                $platform = $platform !== '' ? $platform : null;
329	                // Category lives in settings to avoid a schema change for
330	                // what is effectively a free-form tag. Default to 'custom'
331	                // for older rows that pre-date the category field.
332	                $category = is_string($settings['category'] ?? null)
333	                    ? strtolower(trim((string) $settings['category']))
334	                    : 'custom';
335	
336	                $title = is_string($block->title) ? trim($block->title) : '';
337	                $url = is_string($block->url) ? trim($block->url) : '';
338	
339	                // Resilience: older link rows can have empty title/url at rest
340	                // — settings.platform + settings.handle are the source of truth
341	                // there. Rebuild both from the platform config so the row still
342	                // renders on Hydrogen without requiring a backfill migration.
343	                if (($title === '' || $url === '') && $platform !== null) {
344	                    $config = config("sidest.social_platforms.{$platform}");
345	                    $handle = is_string($settings['handle'] ?? null)
346	                        ? trim((string) $settings['handle'])
347	                        : '';
348	                    if (is_array($config)) {
349	                        if ($title === '' && is_string($config['display_name'] ?? null)) {
350	                            $title = (string) $config['display_name'];
351	                        }
352	                        if ($url === '' && $handle !== '' && is_string($config['url_template'] ?? null)) {
353	                            $url = str_replace('{handle}', $handle, (string) $config['url_template']);
354	                        }
355	                    }
356	                }
357	
358	                return [
359	                    'id' => (string) $block->id,
360	                    'title' => $title,
361	                    'url' => $url,
362	                    'category' => $category !== '' ? $category : 'custom',
363	                    'platform' => $platform,
364	                ];
365	            })
366	            ->filter(fn (array $item) => $item['title'] !== '' && $item['url'] !== '')
367	            ->values()
368	            ->all();
369	
370	        // Append the synthesized booking link when booking is live + resolved.
371	        // Keeping this controller-side means themes have a single list to
372	        // render rather than special-casing booking everywhere.
373	        if ($bookingEnvelope['state'] === 'live' && is_array($bookingEnvelope['data'])) {
374	            $rows[] = [
375	                'title' => (string) ($bookingEnvelope['data']['title'] ?? 'Book now'),
376	                'url' => (string) ($bookingEnvelope['data']['resolved_url'] ?? ''),
377	                'category' => 'booking',
378	                'platform' => is_string($bookingEnvelope['data']['platform'] ?? null)
379	                    ? $bookingEnvelope['data']['platform']
380	                    : null,
381	            ];
382	            // Filter out the booking link if its url ended up empty.
383	            $rows = array_values(array_filter(
384	                $rows,
385	                fn (array $item) => $item['url'] !== '',
386	            ));
387	        }
388	
389	        return $rows;
390	    }
