441	    /**
442	     * Dashboard writes experience as {role, place, start, end, description}.
443	     * Project to the Hydrogen contract {title, organisation, period} so the
444	     * wire shape mirrors credentials and the theme layer doesn't have to know
445	     * about the source schema differences.
446	     */
447	    private function normaliseExperience($row): ?array
448	    {
449	        if (! is_array($row)) {
450	            return null;
451	        }
452	
453	        // Accept both the current dashboard schema (role/place) and the older
454	        // Hydrogen contract names (title/organisation) so pre-migration rows
455	        // don't silently drop.
456	        $title = trim((string) ($row['role'] ?? $row['title'] ?? ''));
457	        if ($title === '') {
458	            return null;
459	        }
460	
461	        $organisation = trim((string) (
462	            $row['place']
463	            ?? $row['organisation']
464	            ?? $row['organization']
465	            ?? ''
466	        ));
467	
468	        $start = isset($row['start']) && $row['start'] !== '' ? (string) $row['start'] : null;
469	        // A null `end` means "currently active" per the dashboard's
470	        // ExperienceEditorModal contract — render as "Current" so the public
471	        // site reads like a CV, not a blank field.
472	        $rawEnd = $row['end'] ?? null;
473	        $end = is_string($rawEnd) && $rawEnd !== '' ? $rawEnd : null;
474	
475	        if ($start !== null) {
476	            $period = $start.' – '.($end ?? 'Current');
477	        } elseif (isset($row['period']) && $row['period'] !== '') {
478	            $period = (string) $row['period'];
479	        } else {
480	            $period = null;
481	        }
482	
483	        return [
484	            'title' => $title,
485	            'organisation' => $organisation,
486	            'period' => $period,
